import { readFile, writeFile } from "node:fs/promises";
const root = new URL("../../../", import.meta.url);
const source = await readFile(new URL("src/pi-durable/reset.ts", root), "utf8");
const messages = await readFile(
  new URL("src/pi-harness/messages.ts", root),
  "utf8",
);
const generated =
  "// Generated by scripts/reuse-reset-policy.mjs from the ECS runtime. Do not edit.\n" +
  'import type { Message } from "@earendil-works/pi-ai";\ntype AgentMessage = Message;\n' +
  source.slice(
    source.indexOf("/** The most history"),
    source.indexOf("/**\n * The context"),
  ) +
  source.slice(
    source.indexOf("/** The last `count`"),
    source.indexOf("export type ContextReset"),
  ) +
  messages.slice(
    messages.indexOf("export const COMPACTION_SUMMARY_PREFIX"),
    messages.indexOf("export interface CompactionSummaryMessage"),
  );
const output = new URL("../src/reset-policy.ts", import.meta.url);
if (process.argv.includes("--check")) {
  if ((await readFile(output, "utf8")) !== generated)
    throw new Error("Workers reset policy drifted from src");
} else await writeFile(output, generated);
